static double tree_predict(int n_nodes, const int* feature, const double* threshold,
                            const int* left, const int* right, const double* value,
                            const double* feats) {
    int node = 0;
    while (feature[node] >= 0) {
        if (feats[feature[node]] <= threshold[node]) node = left[node];
        else node = right[node];
    }
    return value[node];
}

